/*
 * V8 ApiEngine
 * ApiEngineKey: get-microi-store
 * Version: v1.1.3
 * 功能说明：
 * 1. 获取主库 iTdos 应用商城列表。
 * 2. Action=CheckOfficialUpdates 时，检测当前租户官方应用未安装/需更新提醒。
 * 3. 返回应用商城源地址和安装状态，支持安装、更新、重新安装、异常按钮显隐。
 */

var PARAM = V8.Param || {};
var ACTION = PARAM.Action || PARAM.action || "";
var OFFICIAL_CATEGORY_TEXT = "官方应用";
var APP_STORE_SOURCE_API_BASE = "https://api.itdos.com";
var APP_STORE_SOURCE_OS_CLIENT = "iTdos";

function toText(value) {
  if (value === null || value === undefined) return "";
  return String(value);
}

function toLowerKey(value) {
  return toText(value).trim().toLowerCase();
}

function stampAppStoreSource(row) {
  row = row || {};
  row.StoreApiBase = APP_STORE_SOURCE_API_BASE;
  row.AppStoreApiBase = APP_STORE_SOURCE_API_BASE;
  row.StoreOsClient = APP_STORE_SOURCE_OS_CLIENT;
  row.AppStoreOsClient = APP_STORE_SOURCE_OS_CLIENT;
  return row;
}

function getFirst(row, names) {
  if (!row) return "";
  for (var i = 0; i < names.length; i++) {
    var name = names[i];
    if (row[name] !== null && row[name] !== undefined && row[name] !== "") {
      return row[name];
    }
  }
  return "";
}

function toArray(value) {
  var list = [];
  if (!value) return list;
  if (value.length !== undefined) {
    for (var i = 0; i < value.length; i++) {
      list.push(value[i]);
    }
    return list;
  }
  return list;
}

function hasValue(row, fieldName) {
  if (!row || !fieldName) return false;
  var value = row[fieldName];
  return value !== null && value !== undefined && value !== "";
}

function splitVersion(version) {
  var text = toText(version).replace(/^v/i, "");
  var parts = text.split(".");
  var result = [];
  for (var i = 0; i < parts.length; i++) {
    var numText = parts[i].replace(/[^0-9]/g, "");
    var num = parseInt(numText || "0", 10);
    result.push(isNaN(num) ? 0 : num);
  }
  return result;
}

function compareVersion(newVersion, oldVersion) {
  var a = splitVersion(newVersion);
  var b = splitVersion(oldVersion);
  var len = Math.max(a.length, b.length);
  for (var i = 0; i < len; i++) {
    var av = a[i] || 0;
    var bv = b[i] || 0;
    if (av > bv) return 1;
    if (av < bv) return -1;
  }
  return 0;
}

function addInstalledKey(map, key, row) {
  var text = toLowerKey(key);
  if (text && !map[text]) {
    map[text] = row;
  }
}

function buildInstalledMap(installedVersions) {
  var map = {};
  var list = toArray(installedVersions);
  for (var i = 0; i < list.length; i++) {
    var row = list[i] || {};
    addInstalledKey(map, getFirst(row, ["AppId", "AppKey", "StoreAppId", "MicroiStoreAppId"]), row);
    addInstalledKey(map, getFirst(row, ["StoreId", "MicroiStoreId", "AppStoreId"]), row);
    addInstalledKey(map, getFirst(row, ["AppName", "Name", "Title"]), row);
    addInstalledKey(map, row.Id, row);
  }
  return map;
}

function pickAppKey(app) {
  return getFirst(app, ["AppId", "AppKey", "Id", "AppName"]);
}

function pickInstalledVersion(row) {
  return getFirst(row, ["AppVersionInstall", "InstalledVersion", "AppVersion", "Version", "PackageVersion", "StoreVersion", "CurrentVersion"]);
}

function getInstalledRowsFromTenant() {
  try {
    var result = V8.FormEngine.GetTableData("sys_microistoreversion", {
      _SelectFields: [
        "Id",
        "StoreId",
        "AppId",
        "AppName",
        "AppVersion",
        "AppVersionInstall",
        "InstallStatus",
        "InstallTime",
        "UpdateTime"
      ],
      _PageIndex: 1,
      _PageSize: 5000
    });
    if (result && result.Code === 1 && result.Data) {
      return toArray(result.Data);
    }
  } catch (error) {
    console.log("getInstalledRowsFromTenant error: " + error);
  }
  return [];
}

function getInstalledRows() {
  var hasExternalRows = hasValue(PARAM, "InstalledVersions") || hasValue(PARAM, "InstalledApps");
  var paramRows = PARAM.InstalledVersions || PARAM.InstalledApps || [];
  var list = toArray(paramRows);
  if (hasExternalRows) {
    return list;
  }
  return getInstalledRowsFromTenant();
}

function findInstalledApp(installedMap, app) {
  return installedMap[toLowerKey(pickAppKey(app))] ||
    installedMap[toLowerKey(app.Id)] ||
    installedMap[toLowerKey(app.AppId)] ||
    installedMap[toLowerKey(app.AppName)];
}

function getInstallState(app, installed) {
  var latestVersion = toText(app.AppVersion || "");
  if (!installed) {
    return {
      StoreInstallStatus: "Uninstalled",
      StoreInstallStatusText: "未安装",
      StoreInstallActionName: "安装",
      AppVersionInstall: "",
      InstalledVersion: ""
    };
  }

  var installedVersion = pickInstalledVersion(installed);
  var compare = latestVersion && installedVersion ? compareVersion(latestVersion, installedVersion) : 0;
  if (compare > 0) {
    return {
      StoreInstallStatus: "Outdated",
      StoreInstallStatusText: "可更新",
      StoreInstallActionName: "更新",
      AppVersionInstall: installedVersion,
      InstalledVersion: installedVersion
    };
  }
  if (compare < 0) {
    return {
      StoreInstallStatus: "Abnormal",
      StoreInstallStatusText: "版本异常",
      StoreInstallActionName: "异常",
      AppVersionInstall: installedVersion,
      InstalledVersion: installedVersion
    };
  }
  return {
    StoreInstallStatus: "Installed",
    StoreInstallStatusText: "已安装",
    StoreInstallActionName: "重新安装",
    AppVersionInstall: installedVersion,
    InstalledVersion: installedVersion
  };
}

function applyInstallState(app, installedMap) {
  var state = getInstallState(app, findInstalledApp(installedMap, app));
  for (var key in state) {
    app[key] = state[key];
  }
  return app;
}

function findStoreCategoryField() {
  var candidates = ["AppCategory", "Category", "AppType", "Type", "StoreCategory"];
  try {
    var tableResult = V8.FormEngine.GetFormData("diy_table", {
      _Where: [["Name", "=", "sys_microistore"]],
      _SelectFields: ["Id", "Name"]
    });
    if (!tableResult || tableResult.Code !== 1 || !tableResult.Data || !tableResult.Data.Id) {
      return "";
    }
    var fieldResult = V8.FormEngine.GetTableData("diy_field", {
      _Where: [["TableId", "=", tableResult.Data.Id]],
      _SelectFields: ["Name", "Label"],
      _PageSize: 5000
    });
    var fields = fieldResult && fieldResult.Code === 1 ? toArray(fieldResult.Data) : [];
    for (var i = 0; i < fields.length; i++) {
      var fieldName = toText(fields[i].Name);
      for (var j = 0; j < candidates.length; j++) {
        if (fieldName === candidates[j]) {
          return fieldName;
        }
      }
      var label = toText(fields[i].Label);
      if (label === "应用类别" || label === "应用分类") {
        return fieldName;
      }
    }
  } catch (error) {
    console.log("findStoreCategoryField error: " + error);
  }
  return "";
}

function normalizeOfficialCategory(categoryField) {
  if (!categoryField) {
    return 0;
  }
  var updated = 0;
  try {
    var rowsResult = V8.FormEngine.GetTableData("sys_microistore", {
      _SelectFields: ["Id", categoryField],
      _PageIndex: 1,
      _PageSize: 5000
    });
    var rows = rowsResult && rowsResult.Code === 1 ? toArray(rowsResult.Data) : [];
    for (var i = 0; i < rows.length; i++) {
      var item = rows[i] || {};
      if (toText(item[categoryField]) !== OFFICIAL_CATEGORY_TEXT && item.Id) {
        var updateModel = { Id: item.Id };
        updateModel[categoryField] = OFFICIAL_CATEGORY_TEXT;
        var uptResult = V8.FormEngine.UptFormData("sys_microistore", updateModel);
        if (uptResult && uptResult.Code === 1) {
          updated++;
        }
      }
    }
  } catch (error) {
    console.log("normalizeOfficialCategory error: " + error);
  }
  return updated;
}

function buildKeywordWhere(keyword, categoryField, officialOnly) {
  var where = [];
  if (officialOnly && categoryField) {
    where.push([categoryField, "=", OFFICIAL_CATEGORY_TEXT]);
  }
  if (keyword) {
    if (where.length > 0) {
      where.push(["AND", "(", "AppName", "Like", keyword]);
    } else {
      where.push(["(", "AppName", "Like", keyword]);
    }
    where.push(["OR", "AppId", "Like", keyword]);
    where.push(["OR", "AppVersion", "Like", keyword]);
    where.push(["OR", "AppAuthor", "Like", keyword]);
    where.push(["OR", "AppDetail", "Like", keyword, ")"]);
  }
  return where;
}

function getOfficialApps(categoryField) {
  var where = [];
  if (categoryField) {
    where.push([categoryField, "=", OFFICIAL_CATEGORY_TEXT]);
  }
  return V8.FormEngine.GetTableData("sys_microistore", {
    _SelectNotFields: ["AppPakcet"],
    _Where: where,
    _PageSize: PARAM._PageSize || 5000,
    _PageIndex: 1,
    OsClient: V8.OsClient
  });
}

function checkOfficialUpdates() {
  var categoryField = findStoreCategoryField();
  var normalizedRows = normalizeOfficialCategory(categoryField);
  var officialResult = getOfficialApps(categoryField);
  if (!officialResult || officialResult.Code !== 1) {
    return officialResult;
  }

  var apps = toArray(officialResult.Data);
  var installedMap = buildInstalledMap(getInstalledRows());
  var notices = [];
  var installedCount = 0;

  for (var i = 0; i < apps.length; i++) {
    var app = apps[i] || {};
    var key = pickAppKey(app);
    var installed = findInstalledApp(installedMap, app);
    var latestVersion = toText(app.AppVersion || "");
    if (!installed) {
      notices.push({
        Status: "Uninstalled",
        AppId: app.AppId,
        StoreId: app.Id,
        AppName: app.AppName,
        AppVersion: latestVersion,
        AppAuthor: app.AppAuthor,
        AppUpdateTime: app.AppUpdateTime,
        AppPreview: app.AppPreview,
        StoreApiBase: APP_STORE_SOURCE_API_BASE,
        AppStoreApiBase: APP_STORE_SOURCE_API_BASE,
        StoreOsClient: APP_STORE_SOURCE_OS_CLIENT,
        AppStoreOsClient: APP_STORE_SOURCE_OS_CLIENT
      });
      continue;
    }

    installedCount++;
    var installedVersion = pickInstalledVersion(installed);
    if (latestVersion && installedVersion && compareVersion(latestVersion, installedVersion) > 0) {
      notices.push({
        Status: "Outdated",
        AppId: app.AppId,
        StoreId: app.Id,
        AppName: app.AppName,
        AppVersion: latestVersion,
        InstalledVersion: installedVersion,
        AppAuthor: app.AppAuthor,
        AppUpdateTime: app.AppUpdateTime,
        AppPreview: app.AppPreview,
        StoreApiBase: APP_STORE_SOURCE_API_BASE,
        AppStoreApiBase: APP_STORE_SOURCE_API_BASE,
        StoreOsClient: APP_STORE_SOURCE_OS_CLIENT,
        AppStoreOsClient: APP_STORE_SOURCE_OS_CLIENT
      });
    } else if (latestVersion && installedVersion && compareVersion(latestVersion, installedVersion) < 0) {
      notices.push({
        Status: "Abnormal",
        AppId: app.AppId,
        StoreId: app.Id,
        AppName: app.AppName,
        AppVersion: latestVersion,
        InstalledVersion: installedVersion,
        AppAuthor: app.AppAuthor,
        AppUpdateTime: app.AppUpdateTime,
        AppPreview: app.AppPreview,
        StoreApiBase: APP_STORE_SOURCE_API_BASE,
        AppStoreApiBase: APP_STORE_SOURCE_API_BASE,
        StoreOsClient: APP_STORE_SOURCE_OS_CLIENT,
        AppStoreOsClient: APP_STORE_SOURCE_OS_CLIENT
      });
    }
  }

  return {
    Code: 1,
    Data: {
      Notices: notices,
      NoticeCount: notices.length,
      OfficialCount: apps.length,
      InstalledCount: installedCount,
      CategoryField: categoryField,
      CategoryNormalizedRows: normalizedRows,
      CheckedAt: DateNow("yyyy-MM-dd HH:mm:ss")
    }
  };
}

if (ACTION === "CheckOfficialUpdates" || ACTION === "CheckUpdates" || ACTION === "OfficialNotice") {
  return checkOfficialUpdates();
}

var pageIndex = PARAM._PageIndex || 1;
var pageSize = PARAM._PageSize || 15;
var keyword = PARAM._Keyword || "";
var categoryField = findStoreCategoryField();
if (PARAM.NormalizeOfficialCategory === true || PARAM.NormalizeOfficialCategory === "true") {
  normalizeOfficialCategory(categoryField);
}
var _where = buildKeywordWhere(keyword, categoryField, PARAM.OfficialOnly === true || PARAM.OfficialOnly === "true");
var result = V8.FormEngine.GetTableData("sys_microistore", {
  _SelectNotFields: ["AppPakcet"],
  _Where: _where,
  _PageSize: pageSize,
  _PageIndex: pageIndex,
  OsClient: V8.OsClient
});
if (result && result.Code === 1 && result.Data) {
  var installedRows = getInstalledRows();
  var installedMap = buildInstalledMap(installedRows);
  var data = toArray(result.Data);
  for (var i = 0; i < data.length; i++) {
    stampAppStoreSource(applyInstallState(data[i], installedMap));
  }
}
return result;
